.card {
  font-family: arial;
  font-size: 20px;
  text-align: center;
  color: black;
  background-color: white;
}

@charset "utf-8";
@font-face {
	font-family: "Yu Mincho";
	src:
		local("Yu Mincho"),
		local("游明朝"),
		url("_yumin.ttf");
}
@font-face {
	font-family: "Yu Mincho";
	src:
		local("Yu Mincho Demibold"),
		local("游明朝 Demibold"),
		url("_yumindb.ttf");
	font-weight: 600;
}
@font-face {
	font-family: "KanjiStrokeOrders";
	src:
		local("KanjiStrokeOrders"),
		url('_kso.ttf');
}

* { box-sizing: border-box; padding: 0; margin: 0; }
.card {
	background-color: #FFFAF0;
	color: #2A1B0A;
	font-family:	"Noto Serif",
									"Noto Serif CJK JP",
									Yu Mincho,
									"Liberation Serif",
									"Times New Roman",
									Times, Georgia,
									Serif;
	font-size: 24px;
	text-align: left;
	line-height: 1.4;
	max-width: 800px;
	margin: 20px auto;
}
.card1 { }
.card2 .jpsentence ruby rt { opacity: 0; }
.card2 .jpsentence:hover ruby rt { opacity: 1; }

hr { margin: 2px 0; clear: both; }
b { font-weight: 600; }

/* links */
a { color: #532f2f; }
a:hover { color: #722a2a ; }
a.hint { text-decoration: none; display: block; }

/* Hide furigana on front */
nokana ruby rt { opacity:0.0; font-size:0; display: none; }
notext b { background-color: black; color:transparent; }

/* Top */
header { font-size: 14px; line-height: 14px; clear: both; }

/* Japanese sentence */
.jpsentence { font-size: 35px; }
.jpsentence b { color: SaddleBrown; }

.tags {
	font-family:	"Noto Sans",
									"Noto Sans CJK JP",
									"Liberation Sans",
									Arial,
									Sans,
									sans-serif;
	text-align: center;
	display: inline-block;
	text-transform: lowercase;
	background-color: #333;
	color: #FFFAF0;
	font-weight: bold;
	padding: 1px 3px;
	margin: 0;
	cursor: pointer;
	border-radius: 3px;
	font-size: 12px;
	line-height: 14px;
}

/* AnkiDroid replay button */
.replaybutton { margin: 0; margin-right: 3px; text-decoration: none; }
.replaybutton span  { padding: 0; font-size: 16px; }
.replaybutton span svg {
	fill: #FFFAF0;
	background: #333;
	border-radius: 3px;
	vertical-align: top; 
	min-width: 16px;
	min-height: 16px;
}

/* PC replay button */
a.replay-button { top: -.125em;  position: relative; }
a.replay-button svg {
	height: 1em;
	width: 1em;
}
a.replay-button svg path { fill: #FFFAF0; }
a.replay-button svg circle { fill: #333; }

/* footer and dictionaries */
footer {font-size: 16px; text-align: center; }
footer>a { text-decoration: none; }
footer > a:after {content:"·";  color: brown; display: inline-block; width: 6px; }
footer > a:last-child:after {content:""; width: 0; }

/* definitions and notes */
.vocab { margin-top: 16px; }
.vocab div { display: inline-block; }
.vocab  br { display: none; }
.vocab > .tags { vertical-align: top; }
.notes > .tags { vertical-align: bottom; }

/* Production cards */
.production b { visibility: hidden; }
.strokeorder {
	text-align: center;
	font-size: 150px;
	font-family: KanjiStrokeOrders;
}

/* Fix for Yomichan defs */
ul, ol {
  list-style-type: none; 
  display: inline;
  margin: 0px;
  padding: 0px;
}

/* Fix for Yomichan pitch accents */
.vocab ol > li { display: inline; }
.vocab ol > li:after { content: "・"; }
.vocab ol > li:last-child:after { content: ""; }

