.kanjipopup ruby rt { visibility: hidden; }
.kanjipopup ruby:active rt { visibility: visible; }
.kanjipopup ruby:hover rt { visibility: visible; }

/* 
   AESTHETIC: ACADEMIC MINIMALIST (ANKI-NATIVE)
   -------------------------
   Built for speed, focus, and multi-device consistency. 
   Follows Anki's standard centering and night mode conventions.
*/

/* Base Card Styling */
.card {
  font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", -apple-system, sans-serif;
  font-size: 19px;
  line-height: 1.5;
  text-align: center;
  color: #2D3748;
  background-color: #FFFFFF;
  padding: 20px;
  margin: 0;
}

/* Container for Desktop/Mobile sizing */
.card-front, .card-back {
  max-width: 650px; /* Better for reading lines */
  margin: 0 auto;
}

/* Metadata Header (Lesson & Pattern) */
.lesson-info {
  display: inline-block;
  font-size: 14px;
  font-weight: 600;
  color: #718096;
  background: #F7FAFC;
  padding: 4px 12px;
  border-radius: 100px;
  border: 1px solid #E2E8F0;
  margin-bottom: 25px;
}

/* The Core Focus: Large, clear Japanese */
.sentence-placeholder, .sentence-complete {
  font-size: 1.5em; 
  font-weight: 800;
  color: #1A202C;
  margin: 20px 0;
  letter-spacing: 0.02em;
}

/* Cloze-style highlight for the answer */
.grammar-highlight {
  color: #C53030 !important; /* Professional Red */
  background-color: #FFF5F5 !important;
  font-weight: bold !important;
  padding: 2px 4px !important;
  border-radius: 4px !important;
}

/* Translation secondary text */
.translation {
  font-size: 0.9em;
  color: #4A5568;
  margin-top: 15px;
  padding: 10px;
  border-top: 1px solid #EDF2F7;
}

/* Interactive elements: Audio */
.audio-section {
  margin: 20px 0;
}

/* --- Explanations & Content --- */
.grammar-section, .additional-notes, .detailed-section {
  text-align: left; /* Switch to left for longer text readability */
  margin-top: 30px;
  padding: 15px;
  background: #FBFCFE;
  border: 1px solid #EBF4FF;
  border-radius: 10px;
}

h3 {
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #3182CE;
  margin: 0 0 12px 0;
  border-bottom: 2px solid #EBF8FF;
  padding-bottom: 4px;
}

.formation {
  font-size: 15px;
  background: #EDF2F7;
  padding: 10px 15px;
  border-radius: 6px;
  margin-bottom: 12px;
  font-family: Menlo, Monaco, Consolas, "Courier New", monospace;
  word-break: break-all;
}

.detailed-content, .notes-content {
  font-size: 15px;
  color: #4A5568;
}

/* Grammar formation helpers */
.grammar-connection {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}
.g-block { background: #E2E8F0; padding: 2px 6px; border-radius: 4px; font-size: 13px; }
.wt-verb { background: #C6F6D5; color: #22543d; }
.wt-noun { background: #FEEBC8; color: #744210; }
.arrow { color: #A0AEC0; }

/* Night Mode Support (Standard Anki Classes) */
.nightMode.card, .night_mode .card {
  background-color: #2D3748;
  color: #E2E8F0;
}

.nightMode .lesson-info, .night_mode .lesson-info {
  background: #1A202C;
  color: #A0AEC0;
  border-color: #4A5568;
}

.nightMode .sentence-placeholder, .nightMode .sentence-complete,
.night_mode .sentence-placeholder, .night_mode .sentence-complete {
  color: #FFFFFF;
}

.nightMode .grammar-highlight, .night_mode .grammar-highlight {
  color: #FEB2B2 !important;
  background-color: #742A2A !important;
}

.nightMode .translation, .night_mode .translation {
  border-top-color: #4A5568;
  color: #CBD5E0;
}

.nightMode .grammar-section, .nightMode .additional-notes, .nightMode .detailed-section,
.night_mode .grammar-section, .night_mode .additional-notes, .night_mode .detailed-section {
  background: #1A202C;
  border-color: #2D3748;
}

.nightMode h3, .night_mode h3 {
  color: #63B3ED;
  border-bottom-color: #2A4365;
}

.nightMode .formation, .night_mode .formation {
  background: #2D3748;
  color: #CBD5E0;
}

/* --- Mobile Specific Fixes --- */
@media (max-width: 500px) {
  .card { font-size: 17px; padding: 15px; }
  .sentence-placeholder, .sentence-complete { font-size: 1.3em; }
}

/* --- Sentence Structure Formatting --- */
.structure-diagram, .structure_diagram {
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  white-space: pre-wrap;
  word-wrap: break-word;
  background-color: #F7FAFC; /* Match existing academic background */
  padding: 15px;
  border-radius: 8px;
  border: 1px solid #E2E8F0;
  font-size: 14px;
  line-height: 1.6;
  color: #2D3748;
  text-align: left;
  margin: 20px 0;
  overflow-x: auto;
}

.nightMode .structure-diagram, .nightMode .structure_diagram,
.night_mode .structure-diagram, .night_mode .structure_diagram {
  background-color: #1A202C; /* Match night mode sections */
  border-color: #2D3748;
  color: #E2E8F0;
}

/* --- Audio Hints & Promo --- */
.sample-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #38A169;
  background: #F0FFF4;
  border: 1px solid #C6F6D5;
  padding: 2px 8px;
  border-radius: 100px;
  margin-bottom: 10px;
  cursor: pointer;
}

.nightMode .sample-badge, .night_mode .sample-badge {
  background: #22543D;
  color: #9AE6B4;
  border-color: #276749;
}

.audio-locked {
  margin: 10px 0;
}

.audio-locked a {
  display: inline-block;
  font-size: 13px;
  color: #A0AEC0 !important;
  text-decoration: none !important;
  padding: 6px 14px;
  border: 1px dashed #E2E8F0;
  border-radius: 8px;
  transition: all 0.2s ease;
  cursor: pointer;
}

.audio-locked a:hover {
  color: #718096 !important;
  border-color: #CBD5E0;
  background: #F7FAFC;
}

.nightMode .audio-locked a, .night_mode .audio-locked a {
  color: #4A5568 !important;
  border-color: #2D3748;
}

.nightMode .audio-locked a:hover, .night_mode .audio-locked a:hover {
  background: #1A202C;
  color: #718096 !important;
}

/* Purchase Fallback Styling */
.purchase-fallback {
  margin-top: 15px;
  font-size: 12px;
  text-align: center;
}

.purchase-fallback details {
  display: inline-block;
  text-align: left;
  background: #F7FAFC;
  border: 1px solid #E2E8F0;
  border-radius: 6px;
  padding: 4px 10px;
  max-width: 90%;
}

.nightMode .purchase-fallback details, .night_mode .purchase-fallback details {
  background: #1A202C;
  border-color: #2D3748;
}

.purchase-fallback summary {
  cursor: pointer;
  color: #718096;
  outline: none;
  user-select: none;
}

.purchase-fallback summary::-webkit-details-marker {
  color: #CBD5E0;
}

.copy-box {
  display: flex;
  gap: 5px;
  margin-top: 8px;
  background: #FFFFFF;
  border: 1px solid #CBD5E0;
  border-radius: 4px;
  padding: 3px;
}

.nightMode .copy-box, .night_mode .copy-box {
  background: #2D3748;
  border-color: #4A5568;
}

.copy-box input {
  flex: 1;
  border: none;
  background: transparent;
  font-size: 11px;
  color: #4A5568;
  padding: 2px 5px;
  outline: none;
  min-width: 0;
}

.nightMode .copy-box input, .night_mode .copy-box input {
  color: #A0AEC0;
}

.copy-box button {
  background: #3182CE;
  color: white;
  border: none;
  border-radius: 3px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.copy-box button:hover {
  background: #2B6CB0;
}

.copy-box button:active {
  background: #2C5282;
}

/* Authorized Version Footer (Soft Protection) */
.authorized-footer {
  margin-top: 50px;
  padding-top: 15px;
  border-top: 1px dashed #E2E8F0;
  font-size: 11px;
  color: #A0AEC0;
  text-align: center;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-style: italic;
  opacity: 0.8;
}

.nightMode .authorized-footer, .night_mode .authorized-footer {
  border-top-color: #48566d;
  color: #4A5568;
}

.auth-id {
  font-family: Menlo, Monaco, Consolas, "Courier New", monospace;
  color: #CBD5E0;
}

.nightMode .auth-id, .night_mode .auth-id {
  color: #2D3748;
}

/* --- Hint Details Toggle (Front Card) --- */
.hint-details {
  margin-top: 30px;
  text-align: center;
}

.hint-summary {
  display: inline-block;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  color: #718096;
  background: transparent;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid #E2E8F0;
  user-select: none;
  transition: all 0.2s ease;
  line-height: 1.4;
  list-style: none; /* Hide default triangle */
}

/* Hide webkit details marker */
.hint-summary::-webkit-details-marker {
  display: none;
}

.hint-summary:hover {
  background: #EDF2F7;
  color: #4A5568;
}

.hint-details[open] .hint-summary {
  margin-bottom: 15px;
  color: #4A5568;
  background: #EDF2F7;
}

.nightMode .hint-summary, .night_mode .hint-summary {
  background: transparent;
  color: #A0AEC0;
  border-color: #4A5568;
}

.nightMode .hint-summary:hover, .night_mode .hint-summary:hover,
.nightMode .hint-details[open] .hint-summary, .night_mode .hint-details[open] .hint-summary {
  background: #2D3748;
  color: #E2E8F0;
}

